from fastapi import FastAPI, HTTPException
from fastapi.responses import FileResponse
from fastapi.staticfiles import StaticFiles
from pathlib import Path
import importlib
from .startup import PassthroughAuth
from .services import db
from .routers import overview, investments, debt, tracker, learning, health, accounts, goals, insurance, salary, imports, entities, settings

app = FastAPI(title='Finance OS')
app.add_middleware(PassthroughAuth)

@app.on_event('startup')
async def startup_event():
    db.init_db()
    db.check_encrypted_volume(db.DB_PATH.parent)

for name in ['overview', 'investments', 'debt', 'tracker', 'learning', 'health', 'accounts', 'goals', 'insurance', 'salary', 'imports', 'entities', 'settings']:
    try:
        mod = importlib.import_module(f'routers.{name}')
        app.include_router(mod.router, prefix='/api/finance')
    except ImportError:
        pass

@app.get('/api/finance/health')
async def health_check():
    return {'status': 'ok'}

HERE = Path(__file__).parent
STATIC = HERE / 'static'
if STATIC.is_dir():
    app.mount('/assets', StaticFiles(directory=STATIC), name='assets')

@app.get('/{full_path:path}')
async def catch_all(full_path: str):
    file_path = STATIC / f'{full_path}.html'
    if file_path.exists():
        return FileResponse(file_path)
    file_path = STATIC / full_path / 'index.html'
    if file_path.exists():
        return FileResponse(file_path)
    file_path = STATIC / 'index.html'
    if file_path.exists():
        return FileResponse(file_path)
    raise HTTPException(404)
